--
-- Table structure for table `community_pending`
--

DROP TABLE IF EXISTS `community_pending`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `community_pending` (
  `id` varchar(64) NOT NULL,
  `name` varchar(128) NOT NULL,
  `address` varchar(255) NOT NULL DEFAULT '',
  `district` varchar(32) NOT NULL DEFAULT '',
  `street` varchar(64) NOT NULL DEFAULT '',
  `village_num` varchar(32) NOT NULL DEFAULT '',
  `attribute` varchar(32) NOT NULL DEFAULT '',
  `source` varchar(64) NOT NULL DEFAULT '深圳市政府数据开放平台-物业管理区域基础信息',
  `status` varchar(16) NOT NULL DEFAULT 'pending' COMMENT 'pending/geocoded/rejected',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `lng` double DEFAULT NULL COMMENT '经度(WGS-84)，众包确认后写入',
  `lat` double DEFAULT NULL COMMENT '纬度(WGS-84)',
  `geocode_source` varchar(32) NOT NULL DEFAULT '' COMMENT 'admin/user',
  `geocoded_at` datetime DEFAULT NULL,
  `poi_id` varchar(64) NOT NULL DEFAULT '' COMMENT '转正后的 poi_community.id',
  `avg_price` int DEFAULT NULL COMMENT '官方成交参考价(元/㎡)',
  `avg_price_source` varchar(32) NOT NULL DEFAULT '' COMMENT 'gov_reference',
  PRIMARY KEY (`id`),
  KEY `idx_cp_status` (`status`),
  KEY `idx_cp_district` (`district`),
  KEY `idx_cp_status_district` (`status`,`district`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='待定位小区（有名称地址但无坐标）';
/*!40101 SET character_set_client = @saved_cs_client */;

