--
-- Table structure for table `poi_community`
--

DROP TABLE IF EXISTS `poi_community`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `poi_community` (
  `id` varchar(64) NOT NULL,
  `name` varchar(128) NOT NULL,
  `address` varchar(255) NOT NULL DEFAULT '',
  `district` varchar(32) NOT NULL DEFAULT '',
  `lng` decimal(10,6) NOT NULL,
  `lat` decimal(10,6) NOT NULL,
  `built_year` smallint DEFAULT NULL,
  `avg_price` int DEFAULT NULL,
  `property_fee` decimal(6,1) DEFAULT NULL,
  `property_company` varchar(64) NOT NULL DEFAULT '' COMMENT '物业公司',
  `water_saving_year` smallint DEFAULT NULL COMMENT '节水型小区获评年度（政府数据集）',
  `surround_bank_count` int NOT NULL DEFAULT '0' COMMENT '1km 内银行网点数',
  `surround_atm_count` int NOT NULL DEFAULT '0' COMMENT '1km 内 ATM 数',
  `nearest_bank_m` int NOT NULL DEFAULT '0' COMMENT '最近银行网点距离(米)',
  `nearby_brand_count` int NOT NULL DEFAULT '0' COMMENT '1km 内银行品牌数',
  `demo_attributes` tinyint(1) NOT NULL DEFAULT '0' COMMENT '字段是否为演示数据',
  `source` varchar(64) NOT NULL DEFAULT 'OpenStreetMap',
  `license` varchar(32) NOT NULL DEFAULT 'ODbL',
  `source_level` varchar(8) NOT NULL DEFAULT 'L1',
  `status` varchar(16) NOT NULL DEFAULT 'active',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `rent_dc` decimal(8,2) DEFAULT NULL COMMENT '小区多层租金(元/㎡·月，政府租赁参考价)',
  `rent_gc` decimal(8,2) DEFAULT NULL COMMENT '小区高层租金',
  `rent_dmd` decimal(8,2) DEFAULT NULL COMMENT '小区低密度租金',
  `developer` varchar(64) NOT NULL DEFAULT '' COMMENT '建设单位/开发商（竣工验收备案）',
  `avg_price_source` varchar(32) NOT NULL DEFAULT 'demo' COMMENT 'demo=演示值 / gov_reference=政府成交参考价',
  `avg_price_demo` int DEFAULT NULL COMMENT '演示均价(哈希生成，不参与筛选/排序/统计)',
  PRIMARY KEY (`id`),
  KEY `idx_comm_geo` (`lat`,`lng`),
  KEY `idx_comm_district` (`district`),
  KEY `idx_comm_price` (`avg_price`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='住宅小区';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `poi_community`
--

LOCK TABLES `poi_community` WRITE;
/*!40000 ALTER TABLE `poi_community` DISABLE KEYS */;
